use vstd::prelude::*;
use vstd::collections::Set;

verus! {

spec fn vec_to_set(v: &Seq<i32>) -> Set<i32> {
    Set::new().insert_elements(|x| v.contains(x))
}

spec fn no_duplicates(v: &Seq<i32>) -> bool {
    forall |i: int, j: int| (0 <= i && i < j && j < v.len() ==> v.index(i) != v.index(j))
}

fn remove_duplicates(nums: Vec<i32>) -> Vec<i32>
    ensures
        // The result contains no duplicates
        no_duplicates(&result@),

        // The set of elements in the result is the same as that in the input
        vec_to_set(&result@) == vec_to_set(&nums@),
{
    let mut seen = std::collections::HashSet::new();
    let mut result = Vec::new();

    for &num in &nums {
        if !seen.contains(&num) {
            seen.insert(num);
            result.push(num);
        }
    }

    result
}

}
